  CREATE_LOREBOOK_BTN_ID,

  CHARACTER_BOOK_SWITCH_ID,

  PREFETCH_INDICATOR_ID,

  PREFETCH_PROGRESS_TEXT_ID,

  PREFETCH_PROGRESS_BAR_ID,
  appState,
